with valid as (select *, lower(device) as device_lower from sessions where browser is distinct from 'Safari' and started_at < '2025-03-01'), flagged as (select *, case when started_at - lag(started_at) over (partition by customer_id order by started_at, id) > interval 60 days then 1 else 0 end as is_new_burst from valid), sessionized as (select *, sum(is_new_burst) over (partition by customer_id order by started_at, id rows between unbounded preceding and current row) as session_id from flagged), eligible as (select s.* from sessionized s where exists (select 1 from web_events x where x.session_id = s.id and x.event_time <= s.started_at)), matched as (select src.*, sub.id as subscription_id, sub.plan, sub.monthly_fee from eligible src left join subscriptions sub on src.customer_id = sub.customer_id and src.started_at between sub.start_date and sub.end_date) select s.id, s.customer_id, s.device, s.browser, s.started_at, s.country, s.session_id, s.subscription_id, s.plan, (select min(t2.amount) from orders t2 where t2.customer_id = s.customer_id) as min_order_amount from matched s order by started_at nulls first;
